  &DefaultButton;




function filter$systextlanguage(p){
  this.constructor(p);
}
filter$systextlanguage.prototype = new DirEvent();
filter$systextlanguage.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm('controller_filter', p.options._controller);
  this.formFieldValueChange(p.jObject('controller_filter'), 'controller_filter', p.options._controller);
}
filter$systextlanguage.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'filterOk':
      filter$systextlanguageSave('Save', p);
      return false;
    default:
      break;
  }
  return true;
}
filter$systextlanguage.prototype.commandActionClick = function (action, id, po) {
  var p = this._dir;
  switch (id) {
    case 'cmd_restore':
      filter$systextlanguageSave('Restore', p);
      break;
    case 'cmd_saveroot':
      filter$systextlanguageSave('OverwriteRoot', p);
      break;
    default:
      break;
  }
  return true;
}
filter$systextlanguage.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    case 'refresh':
      filter$systextlanguageLoad(p);
      return false
    default:
      break;
  }
  return true;
}
filter$systextlanguage.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
    case 'v':
    case 'e':
      g.data.val(r, 'tag', 1);
      o.closest('tr').addClass('row-bold');
    default:
      break;
  }
}
filter$systextlanguage.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir, pa = p.options.parent;
  switch (cF){
    case 'file_controller':
      filter$systextlanguageLoad(p);
      break;
    case 'controller_filter':
      if (v.trim() == '') {
        p.jObject('file_controller').html(''); 
        p.clearGrid(0);
        return; 
      }
      var time = $.userinfo.val('CommandTimeout'), field = p.field('file_controller');
      p.wait(true, cF);
      var param = { cController: v, cFolder: pa.options.folder};
      $.invoke('GetControllerFiles', param, p, time, function (d) {
        var i, o = p.jObject('file_controller').html('');
        d = new DataTable(d);
        p.options._files = d;
        field.viewInfo.options.option = [];
        for (i = 0; i < d.count(); i++) {
          field.viewInfo.options.option.push({ val: d.val(i, 'val'), text: { lan: d.val(i, 'title') } })
          $('<' + 'option>').attr('value', d.val(i, 'val')).html(d.val(i, 'title')).appendTo(o);
        }
        filter$systextlanguageLoad(p) 
        p.wait(false, cF);
      }, null, function () {
          p.wait(false, cF);
      })
    default:
      break;
  }
}
function filter$systextlanguageSave(action, p) {
  var time = $.userinfo.val('CommandTimeout'), id = p.options.controller + action, df = p.options._files, ifile = p.jObject('file_controller').find(":selected").index(), g = p.grid(0), dt = g.data.clone(['val', 'v', 'e', 'v0', 'e0', 'iline', 'ext'], '[tag] == 1'), m = null;
  if (action == 'Save' && dt.count() == 0) {
    $.showToast('$noChange', p);
    return false;
  }
  p.wait(true, id);
  if (action == 'Save') {
    m = new Memvars();
    m.val('customize', "T", dt.sqlval());
    m = m.val();
  }
  var param = { cAction: action, cController: df.val(ifile, 'filename'), cFolder: df.val(ifile, 'folder'),  oMemvars: m};
  $.invoke('RunTextLanguage', param, p, time, function (d) {
    if (d == "1") {
      $.clearClientCache();
      $.showToast('$Processed', p);
      filter$systextlanguageLoad(p);
    }
    p.wait(false, id);
  }, null, function () {
    p.wait(false, id);
  });
}

function filter$systextlanguageLoad(p) {
  if (!p.valForm('controller_filter') || !p.valForm('file_controller')) {
    p.clearGrid(0);
    return;
  }
  var time = $.userinfo.val('CommandTimeout'), id = p.options.controller, df = p.options._files, ifile = p.jObject('file_controller').find(":selected").index();
  p.wait(true, id);
  var param = { cController: df.val(ifile, 'filename'), cFolder: df.val(ifile, 'folder') };
  $.invoke('GetTextLanguage', param, p, time, function (d) {
    d = new DataTable(d);
    p.appendGrid(0, d, true);
    if (d.count() > 0) {
      p.setInvisible('cmd_restore', d.val(0, 'config') == 0)
      p.setInvisible('cmd_saveroot', d.val(0, 'config') == 0)
    }
    p.wait(false, id);
  }, null, function () {
    p.wait(false, id);
  });
}








